CREATE TABLE parked_items (id INTEGER PRIMARY KEY AUTOINCREMENT,kind INTEGER NOT NULL CHECK (kind IN (0, 1, 2)),character_slot INTEGER NOT NULL CHECK (character_slot BETWEEN -1 AND 2),location INTEGER NOT NULL CHECK (location IN (0, 1)),position INTEGER NOT NULL CHECK (position >= 0),instance_soid INTEGER NOT NULL,definition_hash INTEGER NOT NULL CHECK (definition_hash BETWEEN 1 AND 4294967295),level INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK (quantity > 0),mutation_serial INTEGER NOT NULL CHECK (mutation_serial >= 0),flags INTEGER NOT NULL,socket_policy INTEGER NOT NULL CHECK (socket_policy IN (0, 1)),plug_count INTEGER NOT NULL CHECK (plug_count BETWEEN 0 AND 12),plugs BLOB NOT NULL CHECK (length(plugs) = 48),movement_ability INTEGER NOT NULL,grenade_ability INTEGER NOT NULL,super_ability INTEGER NOT NULL,melee_ability INTEGER NOT NULL,class_ability INTEGER NOT NULL,seen INTEGER NOT NULL CHECK (seen IN (0, 1))) STRICT;
ALTER TABLE parked_items ADD COLUMN placement INTEGER NOT NULL DEFAULT 0 CHECK (placement IN (0, 1));
CREATE TABLE item_objectives (instance_soid INTEGER PRIMARY KEY REFERENCES items(instance_soid) ON DELETE CASCADE,lanes BLOB NOT NULL CHECK (length(lanes) = 32)) STRICT;
ALTER TABLE parked_items ADD COLUMN objectives BLOB CHECK (objectives IS NULL OR length(objectives) = 32);
CREATE TABLE character_helmet_tiers (character_slot INTEGER PRIMARY KEY REFERENCES characters(slot),reaper INTEGER NOT NULL CHECK (reaper BETWEEN 0 AND 3),invader INTEGER NOT NULL CHECK (invader BETWEEN 0 AND 3),collector INTEGER NOT NULL CHECK (collector BETWEEN 0 AND 3),sentry INTEGER NOT NULL CHECK (sentry BETWEEN 0 AND 3)) STRICT;
CREATE TABLE eververse_wallet_sync (account_soid INTEGER PRIMARY KEY CHECK (account_soid <> 0),revision INTEGER NOT NULL CHECK (revision BETWEEN 1 AND 4294967295)) STRICT, WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS character_objective_values (character_soid INTEGER NOT NULL REFERENCES characters(soid) DEFERRABLE INITIALLY DEFERRED,slot INTEGER NOT NULL CHECK (slot BETWEEN 0 AND 32767),value INTEGER NOT NULL CHECK (value BETWEEN 0 AND 2147483647),PRIMARY KEY (character_soid,slot)) STRICT;
